namespace sv_f77003ac68774cab9e7564824c87b7c6.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Interactive components subscribe to OnChange to re-render when theme updates.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    /// <summary>
    /// Batch-update both values with a single notification.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        _theme = theme;
        _accentColor = accentColor;
        NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@using sv_f77003ac68774cab9e7564824c87b7c6.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="badge" style="background-color: @ThemeSvc.AccentColor; color: white;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_f77003ac68774cab9e7564824c87b7c6.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="SelectedColor" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

<p class="mt-3">
    Current: <strong>@ThemeSvc.Theme</strong> /
    <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme { get; set; }
    private string SelectedColor { get; set; } = "#0d6efd";

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeSvc.Theme;
        SelectedColor = ThemeSvc.AccentColor;
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeSvc.SetPreferences(SelectedTheme, SelectedColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeSvc.Theme;
            SelectedColor = ThemeSvc.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

